#pragma once

// The decision "is a door to this destination locked, and why", with no engine types so it can be tested on its own.

#include <cstddef>
#include <cstdint>
#include <map>
#include <set>
#include <string>
#include <utility>
#include <vector>

namespace Archipelago {
namespace Lock {

using Level = std::int16_t;

constexpr Level kStartLevel = 1; // Necrum Mines: where the game starts
constexpr Level kNecrum = 2;     // always open too: the end of the Mines escape drops Abe into it

// The areas (zulags, the game's status-board numbers) that a path holds. Generated by scripts/build_areas.py.
struct AreaEntry final
{
    Level mLevel;
    Level mPath;
    Level mZulagCount;
    Level mZulags[4];
};

// An ElectricWall that a named group switches off (generated by scripts/build_fences.py): the wall's level, path and position.
struct FenceEntry final
{
    const char* mGroup;
    Level mLevel;
    Level mPath;
    int mX;
    int mY;
};

struct UnlockState final
{
    bool mEnforce = false;         // without this nothing is blocked
    bool mAreaAccess = false;      // also block individual areas, not just levels
    bool mLockStartLevel = false;  // TESTING ONLY: treat Necrum Mines like any other level, so it can be locked too
    std::set<Level> mLevels;                       // levels whose pass has arrived
    std::set<std::pair<Level, Level>> mZulags;     // (level, area) whose access item has arrived
    std::map<Level, std::string> mNeeds;           // level -> what it still needs, for the message when its door is tried
    std::set<std::string> mOpenGroups;             // fence groups the client has opened ("open <group>" lines)
};

enum class Reason
{
    eNone,
    eLevelPass,  // the level's pass has not arrived
    eAreaAccess, // none of the areas in the path has had its access item
};

// Levels that never need a pass or area access. `lockStartLevel` is the testing-only switch that makes Necrum Mines lockable.
inline bool IsAlwaysOpen(Level base, bool lockStartLevel)
{
    return (base == kStartLevel && !lockStartLevel) || base == kNecrum;
}

// Ender levels are revisits of a level and share its pass.
inline Level BaseLevel(Level level)
{
    switch (level)
    {
        case 7: return 4;   // Mudanchee Vault Ender
        case 10: return 9;  // Brewery Ender
        case 11: return 3;  // Mudomo Vault Ender
        case 12: return 5;  // FeeCo Depot Ender
        case 13: return 6;  // Barracks Ender
        case 14: return 8;  // Bonewerkz Ender
        default: return level;
    }
}

// Why a door to (level, path) is locked, given where Abe is now. For an area lock, `areas` gets the area numbers the path holds.
inline Reason WhyLocked(
    const UnlockState& state, const AreaEntry* table, std::size_t tableSize, Level level, Level path, Level currentLevel, std::vector<Level>* areas)
{
    if (!state.mEnforce)
    {
        return Reason::eNone;
    }

    const Level base = BaseLevel(level);

    // Not a gameplay level (menu, credits, test level): never blocked.
    if (base < kStartLevel || base > 14 || base == 15)
    {
        return Reason::eNone;
    }

    // Level pass: needed to go into a different level than the one we are in. Necrum Mines and Necrum need none.
    const bool alwaysOpen = IsAlwaysOpen(base, state.mLockStartLevel);
    if (!alwaysOpen && base != BaseLevel(currentLevel) && state.mLevels.count(base) == 0)
    {
        return Reason::eLevelPass;
    }

    // Area access: Necrum Mines and Necrum are open as a whole, Ender levels follow their level's pass.
    if (!state.mAreaAccess || alwaysOpen || level != base)
    {
        return Reason::eNone;
    }
    for (std::size_t i = 0; i < tableSize; i++)
    {
        const AreaEntry& area = table[i];
        if (area.mLevel == base && area.mPath == path)
        {
            for (Level z = 0; z < area.mZulagCount; z++)
            {
                if (state.mZulags.count({base, area.mZulags[z]}) != 0)
                {
                    return Reason::eNone;
                }
            }
            if (areas)
            {
                areas->assign(area.mZulags, area.mZulags + area.mZulagCount);
            }
            return Reason::eAreaAccess; // the path has areas and none of them is unlocked
        }
    }
    return Reason::eNone; // a path with no status board (a hub or corridor) is never blocked
}

// Is this ElectricWall one that an opened group switches off? (Independent of 'enforce': a fence is opened by the line alone.)
inline bool IsFenceOpen(const UnlockState& state, const FenceEntry* table, std::size_t tableSize, Level level, Level path, int x, int y)
{
    if (state.mOpenGroups.empty())
    {
        return false;
    }
    for (std::size_t i = 0; i < tableSize; i++)
    {
        const FenceEntry& fence = table[i];
        if (fence.mLevel == level && fence.mPath == path && fence.mX == x && fence.mY == y && state.mOpenGroups.count(fence.mGroup) != 0)
        {
            return true;
        }
    }
    return false;
}

} // namespace Lock
} // namespace Archipelago
